const TLS = 3;
let S;
let FG = "#ff007f";
let BG = "#101018";
let palettes = [
  ["#FF1493", "#00BFFF", "#FFD700", "#FF4500", "#7B68EE"],
  ["#00F5D4", "#7B2CBF", "#F72585", "#4CC9F0", "#FFE66D"],
  ["#FF595E", "#FFCA3A", "#8AC926", "#1982C4", "#6A4C93"],
  ["#F72585", "#7209B7", "#3A0CA3", "#4361EE", "#4CC9F0"]
];
let currentPal = 0;
let numArr = [];
let clrArr = [];
let animAngle = 0;

function setup() {
  createCanvas(windowWidth, windowHeight);
  S = min(windowWidth, windowHeight) / TLS;
  frameRate(30);
  resetShapeData();
}

function resetShapeData() {
  numArr = [];
  for (let i = 1; i <= TLS * TLS; i++) numArr.push(i);
  shuffle(numArr, true);
  let pal = palettes[currentPal % palettes.length];
  clrArr = [];
  for (let i = 0; i < 5; i++) clrArr.push(pal[i % pal.length]);
}

function draw() {
  let bass = (typeof sub_bass !== 'undefined') ? sub_bass : (typeof bass_ratio !== 'undefined' ? bass_ratio : 0);
  let perc = (typeof percussive !== 'undefined') ? percussive : 0;
  let is_beat_active = (typeof is_beat !== 'undefined' && is_beat);

  if (is_beat_active && frameCount % 30 === 0) {
    currentPal++;
    resetShapeData();
  }

  background(BG);

  S = min(width, height) / TLS;
  let offsetX = (width - S * TLS) / 2;
  let offsetY = (height - S * TLS) / 2;

  animAngle += 0.02 + bass * 0.05;

  push();
  translate(offsetX, offsetY);
  for (let y = 0, i = 0; y < TLS; y++) {
    for (let x = 0; x < TLS; x++, i++) {
      drawShape(x * S, y * S, S, numArr[i % numArr.length], clrArr, bass, perc);
    }
  }
  pop();

  strokeWeight(S * 0.04);
  stroke(clrArr[0] || FG);
  noFill();
  rect(0, 0, width, height);
}

function drawShape(x, y, s, n, pal, bass, perc) {
  const ctx = drawingContext;
  const da = PI / max(1, n);

  push();
  translate(x + s / 2, y + s / 2);
  rotate(animAngle + n * da);
  s *= (0.82 + bass * 0.2);

  strokeWeight(s * 0.025);
  stroke(BG);
  fill(pal[0]);
  rectMode(CENTER);

  const rx = s / 2;
  const ry = 0;

  if (ctx && ctx.createLinearGradient) {
    const linGrad = ctx.createLinearGradient(rx, -ry, -rx, ry);
    for (let i = 0; i < pal.length; i++) {
      linGrad.addColorStop(map(i, 0, max(1, pal.length - 1), 0, 1), pal[i]);
    }
    ctx.fillStyle = linGrad;
  }

  for (let i = 0; i < n; i++) {
    rect(0, 0, s, s / 4, s / 8);
    rotate(-da + perc * 0.05);
  }

  pop();
}
